#include "tree_common.hpp"
int main(int argc,char**argv){if(argc<3)return 1;string root=argv[1];ofstream out(argv[2]);out<<setprecision(28)<<"[";bool first=true;mt19937_64 rng(375923751);for(int L:{3,4,5,6,7}){int li;auto raw=load(root+"/L"+to_string(L)+"_coord.txt",li);vector<int>ids;for(int i=0;i<(int)raw.size();i++)if(!raw[i].terms.empty()&&!raw[i].power&&!raw[i].primitive)ids.push_back(i);for(int k=0;k<12;k++){int id=ids[rng()%ids.size()];OG g;g.g=raw[id];for(auto&t:g.g.terms){OptTerm tt;for(int e=0;e<L*(L+1)/2;e++)if(t.m[e])tt.e.push_back({e,t.m[e],t.co[e]});g.terms.push_back(tt);}auto pr=prepTree(g,L,.8L);LD u[16];for(int j=0;j<2*L-1;j++)u[j]=((LD)(rng()>>12)+.5L)/4503599627370496.L;auto s=drawTree(pr,u);if(k>=6)for(int j=1;j<L;j++)s.lt[j]=(j==1||k>=9)?-(80.L+15.L*k+10.L*j):s.lt[j];LD ratio;auto v=treePoint<LD>(g,L,7-L,s,&ratio);string method="long double";if(ratio<1e-7L){auto q=treePoint<__float128>(g,L,7-L,s,&ratio);for(int j=0;j<=7-L;j++)v[j]=(LD)q[j];method="binary128";if(ratio<1e-24L){auto m=treePoint<MP>(g,L,7-L,s,nullptr);for(int j=0;j<=7-L;j++)v[j]=(LD)m[j];method="decimal100";}}if(!first)out<<',';first=false;out<<"{\"L\":"<<L<<",\"id\":"<<id<<",\"method\":\""<<method<<"\",\"lt\":[";for(int j=0;j<L;j++){if(j)out<<',';out<<'"'<<s.lt[j]<<'"';}out<<"],\"parents\":[";for(int j=0;j<L;j++){if(j)out<<',';out<<s.parents[j];}out<<"],\"sizes\":[";for(int j=0;j<L;j++){if(j)out<<',';out<<s.sizes[j];}out<<"],\"gapnodes\":[";for(int j=0;j<L;j++){if(j)out<<',';out<<s.gapnodes[j];}out<<"],\"order\":[";for(int j=0;j<=L;j++){if(j)out<<',';out<<s.order[j];}out<<"],\"alpha\":[";for(int j=0;j<L;j++){if(j)out<<',';out<<'"'<<s.alpha[j]<<'"';}out<<"],\"values\":[";for(int j=0;j<=7-L;j++){if(j)out<<',';out<<'"'<<v[j]<<'"';}out<<"]}";}}out<<"]\n";}
